    s = evt.key
    check = True
    temp = boxes
    if s == 'left' :
        for bx in temp : 
            if (bx.pos.x == -7) or (board[int(bx.pos.x - 1)][int(bx.pos.y)] == 1) :
                check = False
        if check == True : 
            for bx in boxes : 
                bx.pos.x = bx.pos.x - 1
    if s == 'right' :
