import random
board = [[0 for _ in range(-12, 12 + 1)] for _ in range(-8, 8 + 1)]

for i in range(-8,8 + 1):
    for k in range(-12, 12):
        for j in range(-1, 2):
            box(pos = vec(i, -12, j))
            box(pos = vec(i, 12, j))
            box(pos = vec(-8, k, j))
            box(pos = vec(8, k, j))

a = 0
b = 12
hard = 40
score = 0

while True:
    print('score = ' + str(score), 'hard = ', str(hard // 5))
    shape = random.randint(0, 2)
    print(shape)

    if shape == 0:
        boxes = [box(pos=vec(a, b, 0), color=color.green), box(pos=vec(a, b+1, 0), color=color.green), 
                 box(pos=vec(a+1, b, 0), color=color.green), box(pos=vec(a+1, b+1, 0), color=color.green)]
    elif shape == 1:
        boxes = [box(pos=vec(a, b, 0), color=color.red), box(pos=vec(a, b+1, 0), color=color.red), 
                 box(pos=vec(a, b+2, 0), color=color.red), box(pos=vec(a, b+3, 0), color=color.red)]
    elif shape == 2:
        boxes = [box(pos=vec(a, b, 0), color=color.blue), box(pos=vec(a+1, b, 0), color=color.blue), 
                 box(pos=vec(a+2, b, 0), color=color.blue), box(pos=vec(a+3, b, 0), color=color.blue)]

    canMoveDown = True

    while canMoveDown:
        rate(hard//8)
        for bx in boxes:
            if board[int(bx.pos.x)][int(bx.pos.y) - 1] != 0:
                canMoveDown = False
                break
        if not canMoveDown:
            break

        for bx in boxes:
            bx.pos.y = bx.pos.y - 1
            if bx.pos.y == -11 or board[bx.pos.x][bx.pos.y] == 1 :
                canMoveDown = False


    for bx in boxes:
        board[int(bx.pos.x)][int(bx.pos.y)] = 1
    score += 1
    hard += 1

    gameOver = False
    for i in range(-8, 8 + 1):
        if board[i][12] == 1:
            gameOver = True
            break

    if gameOver:
        break

print("Game Over")

